export function getLocalizedProductDescription(
  product: Pick<Product, 'id' | 'description' | 'descriptionTranslations'>,
  locale: string
): string {
  const lang = locale.split('-')[0];
  if (lang === 'en') return product.description;
  const key = lang as TranslatedLocale;
  const fromProduct = product.descriptionTranslations?.[key];
  if (fromProduct) return fromProduct;
  const fromCatalog = PRODUCT_DESCRIPTION_TRANSLATIONS[product.id]?.[key];
  return fromCatalog || product.description;
}

export function buildDescriptionTranslationsForProduct(id: string): Record<string, string> {
  const entry = PRODUCT_DESCRIPTION_TRANSLATIONS[id];
  if (!entry) return {};
  return { ...entry };
}
